function db(){static $d;if($d)return $d;$d=new PDO('sqlite:'.STORE.'/auth.sqlite');$d->setAttribute(PDO::ATTR_ERRMODE,PDO::ERRMODE_EXCEPTION);$d->setAttribute(PDO::ATTR_DEFAULT_FETCH_MODE,PDO::FETCH_ASSOC);$d->exec('PRAGMA foreign_keys=ON;PRAGMA journal_mode=WAL');return $d;}
function one($q,$p=[]){$s=db()->prepare($q);$s->execute($p);return $s->fetch()?:null;}function rows($q,$p=[]){$s=db()->prepare($q);$s->execute($p);return $s->fetchAll();}function execq($q,$p=[]){$s=db()->prepare($q);return $s->execute($p);}function flash($m){$_SESSION['flash']=$m;}function setting($k,$d=''){return one('SELECT value FROM settings WHERE key=?',[$k])['value']??$d;}function setsetting($k,$v){execq('INSERT INTO settings VALUES(?,?) ON CONFLICT(key) DO UPDATE SET value=excluded.value',[$k,$v]);}
db()->exec("CREATE TABLE IF NOT EXISTS settings(key TEXT PRIMARY KEY,value TEXT NOT NULL);CREATE TABLE IF NOT EXISTS users(id TEXT PRIMARY KEY,username TEXT UNIQUE COLLATE NOCASE,password_hash TEXT,admin INTEGER DEFAULT 0,must_password INTEGER DEFAULT 0,mfa_required INTEGER DEFAULT 0,totp_secret TEXT,totp_enabled INTEGER DEFAULT 0,last_counter INTEGER,source TEXT DEFAULT 'local',ldap_dn TEXT,icon TEXT,active INTEGER DEFAULT 1);CREATE TABLE IF NOT EXISTS groups(id TEXT PRIMARY KEY,name TEXT UNIQUE COLLATE NOCASE,icon TEXT);CREATE TABLE IF NOT EXISTS roles(id TEXT PRIMARY KEY,name TEXT UNIQUE COLLATE NOCASE,icon TEXT);CREATE TABLE IF NOT EXISTS tenants(id TEXT PRIMARY KEY,name TEXT UNIQUE COLLATE NOCASE,icon TEXT);CREATE TABLE IF NOT EXISTS systems(id TEXT PRIMARY KEY,name TEXT UNIQUE COLLATE NOCASE,url TEXT NOT NULL,icon TEXT,internal INTEGER DEFAULT 0,active INTEGER DEFAULT 1);CREATE TABLE IF NOT EXISTS memberships(user_id TEXT,group_id TEXT,PRIMARY KEY(user_id,group_id));CREATE TABLE IF NOT EXISTS assignments(id TEXT PRIMARY KEY,subject_type TEXT,subject_id TEXT,system_id TEXT,role_id TEXT,tenant_id TEXT);CREATE TABLE IF NOT EXISTS ldap_sources(id TEXT PRIMARY KEY,name TEXT,uri TEXT,base_dn TEXT,bind_dn TEXT,bind_secret TEXT,user_filter TEXT,start_tls INTEGER,active INTEGER);CREATE TABLE IF NOT EXISTS token_keys(kid TEXT PRIMARY KEY,pub TEXT,created INTEGER,expires INTEGER);CREATE TABLE IF NOT EXISTS audit(id INTEGER PRIMARY KEY AUTOINCREMENT,ts INTEGER,actor TEXT,action TEXT);CREATE TABLE IF NOT EXISTS rate(k TEXT PRIMARY KEY,n INTEGER,until_ts INTEGER)");
function audit($a){execq('INSERT INTO audit(ts,actor,action) VALUES(?,?,?)',[time(),$_SESSION['uid']??'system',$a]);}function me(){return empty($_SESSION['uid'])?null:one('SELECT * FROM users WHERE id=? AND active=1',[$_SESSION['uid']]);}function need(){if(!$u=me())go('?');return $u;}function admin(){if(!($u=need())['admin'])throw new Exception('Keine Adminrechte.');return $u;}function phash($p){return password_hash($p,defined('PASSWORD_ARGON2ID')?PASSWORD_ARGON2ID:PASSWORD_DEFAULT);}function validpw($p){return strlen($p)>=10;}
function b32e($r){$a='ABCDEFGHIJKLMNOPQRSTUVWXYZ234567';$b='';$o='';foreach(str_split($r) as $c)$b.=str_pad(decbin(ord($c)),8,'0',STR_PAD_LEFT);foreach(str_split($b,5) as $x){$x=str_pad($x,5,'0');$o.=$a[bindec($x)];}return $o;}function b32d($s){$a='ABCDEFGHIJKLMNOPQRSTUVWXYZ234567';$b='';$o='';foreach(str_split($s) as $c)$b.=str_pad(decbin(strpos($a,$c)),5,'0',STR_PAD_LEFT);foreach(str_split($b,8) as $x)if(strlen($x)==8)$o.=chr(bindec($x));return $o;}function totp($s,$c){$h=hash_hmac('sha1',pack('N*',0).pack('N*',$c),b32d($s),true);$o=ord($h[19])&15;$n=((ord($h[$o])&127)<<24)|((ord($h[$o+1])&255)<<16)|((ord($h[$o+2])&255)<<8)|ord($h[$o+3]);return str_pad((string)($n%1000000),6,'0',STR_PAD_LEFT);}function totpok($u,$code){$c=intdiv(time(),30);foreach([-1,0,1] as $w)if(totp($u['totp_secret'],$c+$w)===$code&&($u['last_counter']===null||$c+$w>$u['last_counter'])){execq('UPDATE users SET last_counter=? WHERE id=?',[$c+$w,$u['id']]);return true;}return false;}
function skey(){if(!is_file(STORE.'/.key')){file_put_contents(STORE.'/.key',base64_encode(random_bytes(32)));chmod(STORE.'/.key',0600);}return base64_decode(file_get_contents(STORE.'/.key'));}function enc($v){$n=random_bytes(24);return base64_encode($n.sodium_crypto_secretbox($v,$n,skey()));}function dec($v){if(!$v)return '';$r=base64_decode($v);return sodium_crypto_secretbox_open(substr($r,24),substr($r,0,24),skey())?:'';}
function ldaplogin($name,$pass){if(!extension_loaded('ldap')||$pass==='')return null;foreach(rows('SELECT * FROM ldap_sources WHERE active=1') as $x){$l=@ldap_connect($x['uri']);if(!$l)continue;ldap_set_option($l,LDAP_OPT_PROTOCOL_VERSION,3);ldap_set_option($l,LDAP_OPT_REFERRALS,0);ldap_set_option($l,LDAP_OPT_NETWORK_TIMEOUT,5);if($x['start_tls']&&!@ldap_start_tls($l))continue;if(!@ldap_bind($l,$x['bind_dn']?:null,dec($x['bind_secret'])?:null))continue;$f=str_replace('{username}',ldap_escape($name,'',LDAP_ESCAPE_FILTER),$x['user_filter']);$r=@ldap_search($l,$x['base_dn'],$f,['dn','memberOf']);if(!$r)continue;$e=ldap_get_entries($l,$r);if(($e['count']??0)!==1||!@ldap_bind($l,$e[0]['dn'],$pass))continue;$groups=[];if(isset($e[0]['memberof']))for($i=0;$i<$e[0]['memberof']['count'];$i++)if(preg_match('/^CN=([^,]+)/i',$e[0]['memberof'][$i],$m))$groups[]=$m[1];@ldap_unbind($l);return ['dn'=>$e[0]['dn'],'groups'=>$groups];}return null;}
function ldapuser($name,$info){$u=one('SELECT * FROM users WHERE username=? COLLATE NOCASE',[$name]);if(!$u){$id=uid('usr');execq("INSERT INTO users(id,username,source,ldap_dn) VALUES(?,?,'ldap',?)",[$id,$name,$info['dn']]);$u=one('SELECT * FROM users WHERE id=?',[$id]);}else execq("UPDATE users SET source='ldap',ldap_dn=?,active=1 WHERE id=?",[$info['dn'],$u['id']]);foreach($info['groups'] as $n){$g=one('SELECT * FROM groups WHERE name=? COLLATE NOCASE',[$n]);if(!$g){$gid=uid('grp');execq('INSERT INTO groups VALUES(?,?,NULL)',[$gid,$n]);}else$gid=$g['id'];execq('INSERT OR IGNORE INTO memberships VALUES(?,?)',[$u['id'],$gid]);}return one('SELECT * FROM users WHERE id=?',[$u['id']]);}
function icon($kind,$id){if(empty($_FILES['icon']['tmp_name']))return;$raw=file_get_contents($_FILES['icon']['tmp_name']);$ext=str_starts_with($raw,"\x89PNG")?'png':(str_starts_with($raw,"\xff\xd8\xff")?'jpg':'');if(!$ext||$_FILES['icon']['size']>2097152)throw new Exception('Nur PNG/JPG bis 2 MB.');@mkdir(STORE.'/icons/'.$kind,0750,true);$n=$id.'.'.$ext;move_uploaded_file($_FILES['icon']['tmp_name'],STORE.'/icons/'.$kind.'/'.$n);execq("UPDATE $kind SET icon=? WHERE id=?",[$n,$id]);}
function claims($uid,$sid){$gs=rows('SELECT g.id,g.name FROM groups g JOIN memberships m ON m.group_id=g.id WHERE m.user_id=?',[$uid]);$ids=array_column($gs,'id');$p=[$sid,$uid];$q="SELECT r.name role,t.name tenant FROM assignments a LEFT JOIN roles r ON r.id=a.role_id LEFT JOIN tenants t ON t.id=a.tenant_id WHERE a.system_id=? AND ((a.subject_type='user' AND a.subject_id=?)";if($ids){$q.=" OR (a.subject_type='group' AND a.subject_id IN (".implode(',',array_fill(0,count($ids),'?')).'))';$p=array_merge($p,$ids);}else$q.=')';$a=rows($q,$p);return ['groups'=>array_column($gs,'name'),'roles'=>array_values(array_unique(array_filter(array_column($a,'role')))),'tenants'=>array_values(array_unique(array_filter(array_column($a,'tenant'))))];}
function b64($x){return rtrim(strtr(base64_encode($x),'+/','-_'),'=');}function token($c){$at=time();$exp=$at+LIFE;$kid='tok_'.bin2hex(random_bytes(16));$r=openssl_pkey_new(['private_key_bits'=>2048,'private_key_type'=>OPENSSL_KEYTYPE_RSA]);openssl_pkey_export($r,$priv);$d=openssl_pkey_get_details($r);execq('DELETE FROM token_keys WHERE expires<=?',[time()]);execq('INSERT INTO token_keys VALUES(?,?,?,?)',[$kid,$d['key'],$at,$exp]);$c+=['iat'=>$at,'created_at'=>$at,'nbf'=>$at-5,'exp'=>$exp,'expires_at'=>$exp];$a=b64(json_encode(['alg'=>'RS256','typ'=>'JWT','kid'=>$kid]));$b=b64(json_encode($c));openssl_sign("$a.$b",$sig,$priv,OPENSSL_ALGO_SHA256);return "$a.$b.".b64($sig);}function qr($v){
    $library='/usr/share/phpqrcode/qrlib.php';
    if(!is_file($library))return '';
    require_once $library;
    ob_start();
    QRcode::png($v,null,QR_ECLEVEL_M,6,2);
    $png=ob_get_clean();
    if(!is_string($png)||$png==='')return '';
    return 'data:image/png;base64,'.base64_encode($png);
}
