function head($title){global$error;echo'<!doctype html><html lang="de"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>'.h($title).'</title><style>:root{color-scheme:dark;--b:#080b10;--p:#11161f;--p2:#171e29;--l:#28313d;--t:#edf2f7;--m:#8e9bab;--a:#5ba7ff}*{box-sizing:border-box}body{margin:0;background:var(--b);color:var(--t);font:14px system-ui}.login{min-height:100vh;display:grid;place-items:center}.box,.card{background:var(--p);border:1px solid var(--l);border-radius:12px;padding:20px;box-shadow:0 14px 35px #0003}.box{width:min(390px,92vw)}h1{font-size:20px}label{display:block;color:var(--m);margin:10px 0}input,select{display:block;width:100%;padding:9px;margin-top:5px;background:#090e14;color:var(--t);border:1px solid var(--l);border-radius:4px}input[type=checkbox]{display:inline;width:auto}button,.btn{padding:9px 13px;background:var(--p2);color:var(--t);border:1px solid var(--l);border-radius:8px;cursor:pointer;text-decoration:none;transition:.15s}button:hover,.btn:hover{border-color:#4b5b6f;transform:translateY(-1px)}.primary{background:var(--a);color:#07111b}.error{color:#ff8995}.app{max-width:1080px;margin:auto;padding:24px}.tabs{display:flex;gap:7px;align-items:center;flex-wrap:wrap;margin-bottom:20px;padding:10px 0}.grid{display:grid;grid-template-columns:1fr 1fr;gap:10px}.full{grid-column:1/-1}table{width:100%;border-collapse:collapse;background:var(--p)}th,td{padding:8px;border-bottom:1px solid var(--l);text-align:left}.row{display:flex;gap:7px;align-items:center}.right{margin-left:auto}.icon{width:28px;height:28px;object-fit:cover;border-radius:4px}.page-head{display:flex;align-items:flex-end;justify-content:space-between;gap:16px;margin-bottom:16px}.page-head h1{margin:0 0 4px;font-size:22px}.page-head p{margin:0}.table-wrap{padding:0;overflow:auto}.user-cell{display:flex;align-items:center;gap:9px}.row-actions{display:flex;gap:6px;justify-content:flex-end}.row-actions form{margin:0}.password-resul