if($view==='account'){echo'<div class="grid">';if(!$u['must_password'])echo'<form class="card" method="post" enctype="multipart/form-data"><h2>Icon</h2><input type="hidden" name="csrf" value="'.csrf().'"><input type="hidden" name="action" value="user_icon"><label>PNG oder JPG<input type="file" name="icon" accept="image/png,image/jpeg" required></label><button>Speichern</button></form>';if($u['source']==='local')echo'<form class="card" method="post"><h2>'.($u['must_password']?'Passwort muss geändert werden':'Passwort ändern').'</h2><input type="hidden" name="csrf" value="'.csrf().'"><input type="hidden" name="action" value="password"><label>Aktuelles Passwort<input type="password" name="old" required></label><label>Neues Passwort<input type="password" name="new" minlength="10" required></label><button class="primary">Passwort speichern</button></form>';echo'</div>';}
elseif($view==='users'&&$u['admin']){$gen=$_SESSION['generated']??'';unset($_SESSION['generated']);if($gen)echo'<div class="card password-result"><div><span class="muted">Neues Initialpasswort</span><strong id="generated-password">'.h($gen).'</strong></div><button type="button" onclick="copyText(document.getElementById(\'generated-password\').textContent,this)">Kopieren</button></div>';echo'<div class="page-head"><div><h1>Benutzer</h1><p class="muted">Lokale Konten und zentrale Anmelderegeln.</p></div><button class="primary" type="button" onclick="openUserDialog()">+ Benutzer</button></div><div class="card table-wrap"><table><tr><th>Benutzer</th><th>Quelle</th><th>Admin</th><th>TOTP-Pflicht</th><th>Passwortwechsel</th><th></th></tr>';foreach(rows('SELECT * FROM users ORDER BY username') as $x){$data=h(json_encode(['id'=>$x['id'],'username'=>$x['username'],'admin'=>(bool)$x['admin'],'mfa'=>(bool)$x['mfa_required'],'must'=>(bool)$x['must_password']],JSON_HEX_TAG|JSON_HEX_APOS|JSON_HEX_AMP|JSON_HEX_QUOT));echo'<tr><td><div class="user-cell">'.($x['icon']?'<img class="icon" src="?kind=users&icon='.h($x['icon']).'">':'').'<strong>'.h($x['username']).'</strong></div></td><td>'.h($x['source']).'</td><td>'.($x['admin']?'Ja':'Nein').'</td><td>'.($x['mfa_required']?'Ja':'Nein').'</td><td>'.($x['must_password']?'Ausstehend':'Nein').'</td><td class="row-actions"><button type="button" onclick="openUserDialog(JSON.parse(this.dataset.user))" data-user="'.$data.'">Bearbeiten</button><form method="post"><input type="hidden" name="csrf" value="'.csrf().'"><input type="hidden" name="action" value="reset"><input type="hidden" name="id" value="'.h($x['id']).'"><button>Passwort zurücksetzen</button></form></td></tr>';}echo'</table></div><dialog id="user-dialog"><div class="dialog-head"><div><h2 id="user-dialog-title">Benutzer anlegen</h2><p class="muted">Nur die für die Anmeldung erforderlichen Angaben.</p></div><button type="button" class="icon-button" onclick="userDialog.close()">×</button></div><form method="post" id="user-form" class="dialog-form"><input type="hidden" name="csrf" value="'.csrf().'"><input type="hidden" name="action" value="save_user"><input type="hidden" name="id"><label>Benutzername<input name="username" required autocomplete="off"></label><label>Passwort<div class="password-line"><input type="password" name="password" autocomplete="new-password"><button type="button" onclick="generateAndCopyPassword(this)">Erzeugen & kopieren</button></div></label><div id="password-copy-note" class="copy-note" hidden>Passwort wurde erzeugt und kopiert.</div><div class="checks"><label><input type="checkbox" name="admin"> Administrator</label><label><input type="checkbox" name="mfa"> TOTP verpflichtend</label><label><input type="checkbox" name="must" onchange="enforcePasswordChanged(this)"> Passwortwechsel beim ersten Login erzwingen</label></div><div class="dialog-actions"><button type="button" onclick="userDialog.close()">Abbrechen</button><button class="primary">Speichern</button></div></form></dialog>';}
elseif(in_array($view,['groups','roles','tenants','systems'])&&$u['admin']){echo'<form class="card row" method="post"><input type="hidden" name="csrf" value="'.csrf().'"><input type="hidden" name="action" value="save_entity"><input type="hidden" name="type" value="'.$view.'"><input type="hidden" name="id"><label>Name<input name="name" required></label>'.($view==='systems'?'<label>Link<input type="url" name="url" required></label>':'').'<button class="primary">Anlegen</button></form><table><tr><th>Name</th>'.($view==='systems'?'<th>Link</th>':'').'</tr>';foreach(rows('SELECT * FROM '.$view.($view==='systems'?' WHERE internal=0':'').' ORDER BY name') as $x)echo'<tr><td>'.h($x['name']).'</td>'.($view==='systems'?'<td>'.h($x['url']).'</td>':'').'</tr>';echo'</table>';}
elseif($view==='assignments'&&$u['admin']){$users=rows('SELECT id,username name FROM users');$groups=rows('SELECT id,name FROM groups');echo'<form class="card grid" method="post"><input type="hidden" name="csrf" value="'.csrf().'"><input type="hidden" name="action" value="assign"><label>Typ<select name="subject_type"><option value="user">Benutzer</option><option value="group">Gruppe</option></select></label><label>ID<select name="subject">';foreach([...$users,...$groups] as $x)echo'<option value="'.$x['id'].'">'.h($x['name']).'</option>';echo'</select></label><label>System<select name="system">';foreach(rows('SELECT * FROM systems WHERE internal=0') as $x)echo'<option value="'.$x['id'].'">'.h($x['name']).'</option>';echo'</select></label><label>Rolle<select name="role"><option value="">-</option>';foreach(rows('SELECT * FROM roles') as $x)echo'<option value="'.$x['id'].'">'.h($x['name']).'</option>';echo'</select></label><label>Tenant<select name="tenant"><option value="">-</option>';foreach(rows('SELECT * FROM tenants') as $x)echo'<option value="'.$x['id'].'">'.h($x['name']).'</option>';echo'</select></label><button class="primary">Zuweisen</button></form>';}
elseif($view==='ldap'&&$u['admin']){echo'<form class="card grid" method="post"><input type="hidden" name="csrf" value="'.csrf().'"><input type="hidden" name="action" value="ldap"><input type="hidden" name="id"><label>Name<input name="name" value="Active Directory" required></label><label>URI<input name="uri" value="ldap://dc.example.org:389" required></label><label>Base DN<input name="base_dn" placeholder="DC=example,DC=org" required></label><label>Bind DN<input name="bind_dn"></label><label>Bind-Passwort<input type="password" name="bind_password"></label><label>Filter<input name="filter" value="(|(sAMAccountName={username})(uid={username}))" required></label><label><input type="checkbox" name="tls" checked> StartTLS</label><button class="primary">Speichern</button></form><table><tr><th>Name</th><th>URI</th><th>Base DN</th></tr>';foreach(rows('SELECT * FROM ldap_sources') as $x)echo'<tr><td>'.h($x['name']).'</td><td>'.h($x['uri']).'</td><td>'.h($x['base_dn']).'</td></tr>';echo'</table>';}
elseif($view==='audit'&&$u['admin']){echo'<table><tr><th>Zeit</th><th>Akteur</th><th>Aktion</th></tr>';foreach(rows('SELECT * FROM audit ORDER BY id DESC LIMIT 300') as $x)echo'<tr><td>'.date('Y-m-d H:i:s',$x['ts']).'</td><td>'.h($x['actor']).'</td><td>'.h($x['action']).'</td></tr>';echo'</table>';}
echo <<<'HTML'
</main><script>
const userDialog=document.getElementById('user-dialog');
function openUserDialog(user={}){const f=document.getElementById('user-form');f.reset();f.id.value=user.id||'';f.username.value=user.username||'';f.admin.checked=!!user.admin;f.mfa.checked=!!user.mfa;f.must.checked=!!user.must;f.password.required=!user.id;document.getElementById('user-dialog-title').textContent=user.id?'Benutzer bearbeiten':'Benutzer anlegen';document.getElementById('password-copy-note').hidden=true;userDialog.showModal()}
function securePassword(){const chars='ABCDEFGHJKLMNPQRSTUVWXYZabcdefghijkmnopqrstuvwxyz23456789!@$%+-_';const bytes=new Uint32Array(16);crypto.getRandomValues(bytes);return Array.from(bytes,x=>chars[x%chars.length]).join('')}
async function copyText(value,button){try{await navigator.clipboard.writeText(value);if(button){const old=button.textContent;button.textContent='Kopiert';setTimeout(()=>button.textContent=old,1200)}return true}catch{return false}}
async function generateAndCopyPassword(button){const input=document.querySelector('#user-form [name=password]');input.value=securePassword();input.type='text';input.focus();input.select();const copied=await copyText(input.value,button);const note=document.getElementById('password-copy-note');note.hidden=false;note.textContent=copied?'Passwort wurde erzeugt und kopiert.':'Passwort wurde erzeugt. Zum Kopieren markieren.'}
function enforcePasswordChanged(box){if(!box.checked)return;const input=document.querySelector('#user-form [name=password]');if(!input.value)generateAndCopyPassword(box)}
</script></body></html>
HTML;
